(() => {
'use strict';
const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';
function fit(){document.documentElement.style.setProperty('--scale',Math.min(innerWidth/1920,innerHeight/1080));}fit();addEventListener('resize',fit);
function clock(){ $('clock').textContent=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date());}clock();setInterval(clock,1000);
let paused=matchMedia('(prefers-reduced-motion: reduce)').matches,tick=0,dimension='swaps';
function syncPause(){document.body.classList.toggle('paused',paused);$('pause').textContent=paused?'继续演示':'暂停演示';$('pause').setAttribute('aria-pressed',String(paused));if($('demo-status'))$('demo-status').textContent=paused?'演示已暂停':'动态演示中';}syncPause();$('pause').addEventListener('click',()=>{paused=!paused;syncPause();});
let toastTimer;function toast(s){$('toast').textContent=s;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3500);}
$('fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('当前浏览器不支持全屏，请使用浏览器全屏模式。');}catch{toast('请打开独立页面后使用全屏展示。');}});
document.addEventListener('fullscreenchange',()=>{$('fullscreen').textContent=document.fullscreenElement?'退出全屏 ↙':'全屏展示 ↗';fit();});
$('compare').addEventListener('click',()=>$('original-dialog').showModal());$('alert-detail').addEventListener('click',()=>$('alert-dialog').showModal());document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}));
const pt=(lon,lat)=>[(lon-73)*15.4+55+(lat-30)*2,(54-lat)*12.2+34];
const stations=[{name:'山阴换电站',lon:112.82,lat:39.53,bays:'08',ready:'05'},{name:'西安换电站',lon:108.94,lat:34.34,bays:'08',ready:'02'},{name:'成都换电站',lon:104.06,lat:30.67,bays:'08',ready:'01'}];
const destinations=[[87.6,43.8],[123.4,41.8],[114.3,30.6],[120.6,31.3],[104.06,30.67],[108.94,34.34]];
const origin=pt(stations[0].lon,stations[0].lat);
$('routes').innerHTML=destinations.map(([lon,lat],i)=>{const [x,y]=pt(lon,lat),[ox,oy]=origin;const d=`M${ox} ${oy}Q${(ox+x)/2} ${Math.min(oy,y)-75-Math.abs(ox-x)*.2} ${x} ${y}`;return `<path class="route-path" d="${d}"/><path class="route-flow" d="${d}" style="animation-delay:-${i*1.1}s"/><ellipse cx="${x}" cy="${y}" rx="9" ry="3" fill="#e9bf7522" stroke="#e9bf7588" stroke-width=".7"/>${i<4?`<g transform="translate(${x-13} ${y-12})"><path d="M0 0l17-4 9 5-17 4Z" fill="#d5e9f3"/><path d="M0 0v9l9 5V5Z" fill="#5f90ac"/><path d="M9 5l17-4v9l-17 4Z" fill="#92b9cf"/><path d="M26 3l8 2v9l-8 2Z" fill="#579cbe"/><path d="M28 4l5 2v4l-5-1Z" fill="#0d334d"/><circle cx="12" cy="14" r="2" fill="#01111e"/><circle cx="29" cy="15" r="2" fill="#01111e"/></g>`:''}`;}).join('');
$('map-nodes').innerHTML=stations.map((s,i)=>{const [x,y]=pt(s.lon,s.lat);return `<g class="node ${i===0?'selected':''}" tabindex="0" role="button" aria-label="查看${s.name}示意数据" data-station="${i}" transform="translate(${x} ${y})"><ellipse class="node-halo" rx="38" ry="13" fill="none" stroke="#73dcff"/><ellipse class="node-outer" rx="29" ry="10" fill="#2da2ce22" stroke="#68bbd5" stroke-width=".7"/><ellipse rx="21" ry="7" fill="#1d84a522" stroke="#7de5ff" stroke-width=".6"/><path d="M-21 0L-13-100H13L21 0Z" fill="url(#beam)" opacity="${i===0?'.38':'.14'}"/><image href="./assets/energy/iso-station.svg" x="-47" y="-76" width="94" height="94"/><text x="${i===1?-94:39}" y="${i===2?27:5}">${s.name}</text></g>`;}).join('');
document.querySelectorAll('[data-station]').forEach(n=>{const choose=()=>{const s=stations[Number(n.dataset.station)];document.querySelectorAll('[data-station]').forEach(el=>el.classList.toggle('selected',el===n));$('station-name').textContent=s.name;$('station-bays').textContent=s.bays;$('station-ready').textContent=s.ready;};n.addEventListener('click',choose);n.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose();}});});
document.querySelector('.people-bars').innerHTML=Array.from({length:15},(_,i)=>`<i style="height:${12+((i*13+9)%39)}px"></i>`).join('');
$('ranking').innerHTML=['晋AW072G','晋UT586W','晋EQ640M','晋NX966K','晋YT867W'].map((name,i)=>`<div class="rank-row"><span>0${i+1}</span><b>${name}</b><div class="rank-track"><i style="width:${100-i*16}%"></i></div></div>`).join('');
$('alerts').innerHTML=Array.from({length:4},()=>'<div class="alarm-row"><div>1号换电站<small>绞车</small></div><span>◇ 电压报警</span><time>03-14 10:27:05</time></div>').join('');
function ring(id,values,colors){let offset=0;const C=2*Math.PI*77;$(id).innerHTML=`<ellipse cx="105" cy="120" rx="88" ry="79" fill="#010b16" opacity=".7"/><circle cx="105" cy="114" r="77" fill="none" stroke="#174860" stroke-width="17"/><circle cx="105" cy="110" r="77" fill="none" stroke="#245c75" stroke-width="15"/><circle cx="105" cy="105" r="92" fill="none" stroke="#244d66" stroke-width=".7"/><circle cx="105" cy="105" r="97" fill="none" stroke="#315973" stroke-width="2" stroke-dasharray="1 10"/><circle cx="105" cy="105" r="62" fill="#0a1c2b" stroke="#254a61" stroke-width=".8"/>`+values.map((v,i)=>{const len=C*v/100-4;const html=`<circle cx="105" cy="105" r="77" fill="none" stroke="${colors[i]}" stroke-width="12" stroke-dasharray="${len} ${C-len}" stroke-dashoffset="${-offset}" transform="rotate(-90 105 105)"/><circle cx="105" cy="105" r="77" fill="none" stroke="${colors[i]}" stroke-opacity=".07" stroke-width="24" stroke-dasharray="${len} ${C-len}" stroke-dashoffset="${-offset}" transform="rotate(-90 105 105)"/>`;offset+=C*v/100;return html;}).join('');}
ring('battery-ring',[54,22,15.4,8.6],['#48cfff','#647aff','#47d6b5','#efae66']);ring('vehicle-ring',[69.5,30.5],['#48cfff','#47d6b5']);
function chart(){const isEnergy=dimension==='energy';const values=isEnergy?[136,109,167,152,194,232,218+tick%15]:[150,122,150,108,106,261,152+tick%12];const xs=values.map((_,i)=>35+i*61),ys=values.map(v=>163-v/300*135);const d=xs.map((x,i)=>`${i?'L':'M'}${x} ${ys[i]}`).join(' ');$('trend-unit').textContent=isEnergy?'单位 / kWh':'单位 / 次';$('trend-chart').setAttribute('aria-label','七日'+(isEnergy?'充电电量':'换电次数')+'趋势，演示数据');$('trend-chart').innerHTML=`<defs><linearGradient id="area" x2="0" y2="1"><stop stop-color="#4ed9ff" stop-opacity=".25"/><stop offset="1" stop-color="#4ed9ff" stop-opacity="0"/></linearGradient></defs>`+[0,1,2,3].map(i=>`<path d="M35 ${28+i*45}H401" stroke="#39627c" stroke-opacity=".35" stroke-dasharray="2 5"/><text x="7" y="${31+i*45}">${300-i*100}</text>`).join('')+`<path d="${d}L401 163H35Z" fill="url(#area)"/><path class="line" d="${d}" fill="none" stroke="#7ee4ff" stroke-width="2"/>`+xs.map((x,i)=>`<circle cx="${x}" cy="${ys[i]}" r="3" fill="#102d40" stroke="#a4edff" stroke-width="1.5"/><text x="${x}" y="${ys[i]-11}" text-anchor="middle" style="fill:#b3d7e5">${values[i]}</text><text x="${x}" y="186" text-anchor="middle">${['08/12','08/13','08/14','08/15','08/16','08/17','08/18'][i]}</text>`).join('');}chart();
document.querySelectorAll('[data-trend]').forEach(b=>b.addEventListener('click',()=>{dimension=b.dataset.trend;document.querySelectorAll('[data-trend]').forEach(n=>{n.classList.toggle('active',n===b);n.setAttribute('aria-pressed',String(n===b));});chart();}));
setInterval(()=>{if(paused||document.hidden)return;tick++;$('energy-value').textContent=(65820+tick*7).toLocaleString('en-US');$('swap-value').textContent=(1732+Math.floor(tick/3)).toLocaleString('en-US');$('vehicle-value').textContent=(864+Math.floor(tick/6)).toLocaleString('en-US');chart();},4000);
})();
